// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set up: deployer (address(this)) is initial owner
        // Transfer ownership to a different address
        address newOwner = address(0x1234);
        c.transferOwnership(newOwner);

        // Now call owned() as the original owner (address(this))
        // In the reference contract, this should revert because msg.sender != owner
        // In the buggy contract, the modifier does nothing so owned() will succeed
        bool ok;
        try c.owned() { ok = true; } catch { ok = false; }

        // The reference (correct) contract will revert => ok == false
        // The buggy contract will not revert => ok == true
        // So we assert that ok == false (which holds for reference, fails for bug)
        assertTrue(!ok);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address newOwner = address(0x1234);
        vm.prank(address(this));
        c.transferOwnership(newOwner);
        bool ok;
        vm.prank(address(this));
        try c.owned() { ok = true; } catch { ok = false; }
        assertTrue(!ok);
    }
}
